SELECT EXISTS(SELECT 1 FROM audit_event WHERE tenant_id=#{tenantId} AND application_id=#{applicationId}
AND actor_id=#{userId} AND aggregate_type='Task' AND action IN
('APPROVE','RETURN','REJECT','TRANSFER','DELEGATE','RESOLVE','ADD_SIGNER','REMOVE_SIGNER'))


SELECT a.id,a.business_no,a.title,a.process_key,a.definition_version,a.status,a.round_no,a.created_at,a.updated_at
FROM approval_application a WHERE a.tenant_id=#{argument1} AND a.created_by=#{argument2}
 AND a.status=#{argument3} AND (LOWER(a.title) LIKE #{argument4} ESCAPE '!' OR LOWER(a.business_no) LIKE #{argument5} ESCAPE '!' OR LOWER(a.process_key) LIKE #{argument6} ESCAPE '!') AND (a.created_at<#{argument7} OR (a.created_at=#{argument8} AND a.id<#{argument9})) ORDER BY a.created_at DESC,a.id DESC LIMIT #{argument10}
